Got it — here’s a clean pattern: load JSON first, then override selected fields from environment variables. This keeps errors explicit and makes overrides opt-in per field.

```go
package config

import (
    "encoding/json"
    "fmt"
    "os"
    "strconv"
    "strings"
)

func LoadConfig(path string) (*Config, error) {
    data, err := os.ReadFile(path)
    if err != nil {
        return nil, fmt.Errorf("read config %s: %w", path, err)
    }

    var c Config
    if err := json.Unmarshal(data, &c); err != nil {
        return nil, fmt.Errorf("unmarshal config %s: %w", path, err)
    }

    if err := applyEnvOverrides(&c); err != nil {
        return nil, err
    }
    return &c, nil
}

// applyEnvOverrides overrides config fields from environment variables.
// Convention: CONFIG__<STRUCT>__<FIELD> with double underscore as separator.
// Example: CONFIG__SERVER__PORT=8080  overrides c.Server.Port
func applyEnvOverrides(c *Config) error {
    for _, env := range os.Environ() {
        kv := strings.SplitN(env, "=", 2)
        if len(kv) != 2 {
            continue
        }
        key, val := kv[0], kv[1]
        if !strings.HasPrefix(key, "CONFIG__") {
            continue
        }
        parts := strings.Split(strings.TrimPrefix(key, "CONFIG__"), "__")
        if len(parts) < 2 {
            continue
        }
        // parts[0] = struct name, parts[1:] = field path
        if err := setConfigValue(c, parts, val); err != nil {
            return fmt.Errorf("env override %s: %w", key, err)
        }
    }
    return nil
}

// setConfigValue sets a field value by reflection based on parts.
// Supports basic types: string, int, bool. Extend as needed.
func setConfigValue(c *Config, parts []string, val string) error {
    // Very small reflection helper for demo purposes.
    // For production, consider mapstructure or envconfig library.
    v := reflect.ValueOf(c).Elem()
    // first part: struct field name
    fieldName := strings.Title(strings.ToLower(parts[0]))
    f := v.FieldByName(fieldName)
    if !f.IsValid() {
        return fmt.Errorf("unknown struct %s", parts[0])
    }
    // navigate nested structs
    for i, p := range parts[1:] {
        if i == len(parts[1:])-1 {
            // final field to set
            fieldName = strings.Title(strings.ToLower(p))
            sf := f.FieldByName(fieldName)
            if !sf.IsValid() {
                return fmt.Errorf("unknown field %s.%s", parts[0], p)
            }
            return setFieldValue(sf, val)
        }
        // go deeper
        fieldName = strings.Title(strings.ToLower(p))
        f = f.FieldByName(fieldName)
        if !f.IsValid() || !f.CanSet() {
            return fmt.Errorf("invalid path %v", parts)
        }
        if f.Kind() == reflect.Ptr {
            if f.IsNil() {
                f.Set(reflect.New(f.Type().Elem()))
            }
            f = f.Elem()
        }
    }
    return nil
}

func setFieldValue(f reflect.Value, val string) error {
    if !f.CanSet() {
        return fmt.Errorf("field not settable")
    }
    switch f.Kind() {
    case reflect.String:
        f.SetString(val)
    case reflect.Int, reflect.Int64:
        i, err := strconv.ParseInt(val, 10, 64)
        if err != nil {
            return err
        }
        f.SetInt(i)
    case reflect.Bool:
        b, err := strconv.ParseBool(val)
        if err != nil {
            return err
        }
        f.SetBool(b)
    default:
        return fmt.Errorf("unsupported type %s", f.Kind())
    }
    return nil
}
```

Notes:

* Errors from file read / JSON unmarshal are propagated with context.
* Env var naming uses `CONFIG__STRUCT__FIELD`. Adjust the prefix/separator to your taste.
* The reflection helper is minimal. For real projects the `envconfig` or `mapstructure` libraries handle nested structs, tags, and type conversion more robustly.

