Here is a table-driven test you can drop into `config_test.go`. It covers happy path, env overrides, and error cases.

```go
package config

import (
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
)

type testCase struct {
	name        string
	jsonContent string
	env         map[string]string
	want        Config
	wantErr     bool
}

func TestLoadConfig(t *testing.T) {
	tests := []testCase{
		{
			name: "happy path no overrides",
			jsonContent: `{"Server":{"Port":8080,"Host":"localhost"},"Debug":false}`,
			env:         map[string]string{},
			want: Config{
				Server: struct{ Port int; Host string }{Port: 8080, Host: "localhost"},
				Debug:  false,
			},
		},
		{
			name: "env override port",
			jsonContent: `{"Server":{"Port":8080,"Host":"localhost"},"Debug":false}`,
			env: map[string]string{
				"CONFIG__SERVER__PORT": "9090",
			},
			want: Config{
				Server: struct{ Port int; Host string }{Port: 9090, Host: "localhost"},
				Debug:  false,
			},
		},
		{
			name: "env override host and debug",
			jsonContent: `{"Server":{"Port":8080,"Host":"localhost"},"Debug":false}`,
			env: map[string]string{
				"CONFIG__SERVER__HOST": "0.0.0.0",
				"CONFIG__DEBUG":        "true",
			},
			want: Config{
				Server: struct{ Port int; Host string }{Port: 8080, Host: "0.0.0.0"},
				Debug:  true,
			},
		},
		{
			name:        "invalid json",
			jsonContent: `{invalid json`,
			env:         map[string]string{},
			wantErr:     true,
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			dir := t.TempDir()
			path := filepath.Join(dir, "config.json")
			if err := os.WriteFile(path, []byte(tc.jsonContent), 0644); err != nil {
				t.Fatalf("write temp file: %v", err)
			}

			// set env vars for this case
			for k, v := range tc.env {
				t.Setenv(k, v)
			}
			// ensure no leftover vars from previous cases
			for _, k := range []string{"CONFIG__SERVER__PORT", "CONFIG__SERVER__HOST", "CONFIG__DEBUG"} {
				if _, ok := tc.env[k]; !ok {
					t.Setenv(k, "")
				}
			}

			got, err := LoadConfig(path)
			if tc.wantErr {
				if err == nil {
					t.Fatalf("expected error but got none")
				}
				return
			}
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if got == nil {
				t.Fatalf("got nil config")
			}

			// compare
			if got.Server.Port != tc.want.Server.Port || got.Server.Host != tc.want.Server.Host || got.Debug != tc.want.Debug {
				t.Fatalf("mismatch.\n got  %+v\n want %+v", got, tc.want)
			}
		})
	}
}

func TestLoadConfig_MissingFile(t *testing.T) {
	_, err := LoadConfig("/non/existent/path.json")
	if err == nil {
		t.Fatalf("expected error for missing file")
	}
}
```

Notes:

* `t.Setenv` sets the variable for the duration of the sub-test and cleans up afterwards.
* The test assumes your `Config` type is defined as e.g.:

```go
type Config struct {
	Server struct {
		Port int    `json:"port"`
		Host string `json:"host"`
	} `json:"Server"`
	Debug bool `json:"debug"`
}
```

If your struct is different, adjust the `want` values and the env keys to match your `CONFIG__STRUCT__FIELD` convention.

